@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap');:root{font-family:'DM Sans',sans-serif;color:#e8eef6;background:#0b1018;font-synthesis:none}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}.shell{width:min(1150px,calc(100% - 36px));margin:auto}header{border-bottom:1px solid #273140;background:#0b1018e8;position:sticky;top:0;z-index:5;backdrop-filter:blur(12px)}.nav,.foot,.sectiontop,.dashactions{display:flex;justify-content:space-between;align-items:center;gap:20px}.nav{min-height:78px}.brand{background:none;border:0;color:#fff;font:800 27px Outfit;text-align:left;letter-spacing:-1px}.brand span,.foot strong span{color:#40baff}.brand small{display:block;font:600 9px 'DM Sans';letter-spacing:3px;color:#8494a8;margin-top:0}.nav nav{display:flex;gap:12px;align-items:center}.nav nav button{border:0;background:none;color:#c4ceda;padding:11px;font-size:13px}.nav nav .outline,.outline{border:1px solid #3c4a5b;background:transparent;color:#f1f5fb;padding:12px 17px;border-radius:8px}.hero{padding:95px 0 76px;background:radial-gradient(ellipse at 88% 22%,#163a56 0,transparent 46%)}.eyebrow{color:#55c4ff;letter-spacing:2px;font-size:11px;font-weight:800}.dot{display:inline-block;width:6px;height:6px;background:#55c4ff;border-radius:50%;margin-left:8px}.hero h1,.dashboard h1{font:800 clamp(44px,7vw,85px)/1.04 Outfit;letter-spacing:-3px;margin:18px 0}.hero h1 em{font-style:normal;color:#55c4ff}.hero p{color:#9caec0;max-width:480px;line-height:1.8;font-size:16px}.heroactions{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0 54px}.primary{display:inline-flex;align-items:center;justify-content:center;gap:9px;background:#27a8f4;color:#07111d;border:0;padding:13px 20px;border-radius:8px;font-weight:800}.primary:disabled{opacity:.6}.stats{display:flex;gap:48px;flex-wrap:wrap}.stats div{display:flex;flex-direction:column;gap:4px}.stats strong{font:700 29px Outfit}.stats span,.muted{color:#91a0b1;font-size:13px}.gallery{padding:34px 0 100px}.sectiontop h2{font:700 35px Outfit;margin:9px 0 18px}.tabs{display:flex;gap:10px;overflow-x:auto;border-bottom:1px solid #263243;margin:8px 0 22px}.tabs button{white-space:nowrap;border:0;background:none;color:#a0adbb;padding:12px 14px}.tabs button.active{color:#54c2ff;border-bottom:2px solid #54c2ff}.filters{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:10px;margin-bottom:26px}.filters input,.filters select,input,textarea,select{width:100%;background:#141d29;border:1px solid #344254;border-radius:8px;color:#edf4ff;padding:12px;outline:none}.filters input:focus,input:focus,textarea:focus,select:focus{border-color:#55c4ff}.search{position:relative}.search svg{position:absolute;left:13px;top:13px;color:#8ea2b7}.search input{padding-left:40px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.card{text-align:left;padding:0;background:#141c27;border:1px solid #293747;border-radius:12px;overflow:hidden;color:inherit;transition:transform .15s,border-color .15s}.card:hover{transform:translateY(-4px);border-color:#43b6f9}.cardimage{height:270px;background:linear-gradient(140deg,#1b2e43,#0e1825);display:flex;justify-content:center;align-items:center;position:relative}.cardimage img{width:100%;height:100%;object-fit:contain;padding:12px}.placeholder{width:70%;height:78%;border:2px solid #38516c;border-radius:9px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:7px;background:linear-gradient(135deg,#233e5b,#101e2e);color:#63c9ff}.placeholder span{font:800 62px Outfit}.placeholder small{font-size:9px;letter-spacing:2px;color:#9ac8e4}.status{position:absolute;left:10px;top:10px;background:#0a1726dd;border:1px solid #35536d;padding:5px 9px;border-radius:5px;font-size:10px}.cardinfo{padding:17px}.cardinfo h3{font:700 19px Outfit;margin:7px 0}.empty,.hint{padding:20px;border:1px dashed #3a4a60;border-radius:10px;color:#9baec2;margin:18px 0}.hint{font-size:13px}.dashboard{min-height:65vh;padding:65px 0}.dashboard h1{font-size:42px;letter-spacing:-1px}.panel{background:#141d29;border:1px solid #344254;padding:26px;border-radius:12px}.auth{max-width:400px;display:grid;gap:14px}.auth h2{margin:0}.adminlist{margin-top:20px}.adminrow{padding:15px;border-bottom:1px solid #2c3a4b;display:flex;justify-content:space-between;align-items:center;gap:12px}.adminrow small{color:#8798ab}.adminrow button{border:0;background:transparent;color:#dbe6f2;padding:8px}.notice{position:fixed;bottom:20px;right:20px;background:#18364d;border:1px solid #49baff;padding:12px 15px;border-radius:8px;z-index:20;display:flex;gap:12px;align-items:center}.notice button,.close{background:none;border:0;color:inherit}.overlay{position:fixed;inset:0;background:#03060bd9;z-index:10;display:flex;align-items:center;justify-content:center;padding:16px}.modal{background:#141d29;border:1px solid #354558;border-radius:16px;padding:30px;max-height:92vh;overflow:auto;position:relative;width:min(850px,100%)}.close{position:absolute;right:15px;top:15px}.detailgrid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.detailimage{height:460px;display:flex;align-items:center;justify-content:center;background:#0b1521;border-radius:10px}.detailimage img{max-width:100%;max-height:100%;object-fit:contain}.detail h2{font:700 36px Outfit;margin:15px 0 3px}.detail dl div{display:flex;justify-content:space-between;border-bottom:1px solid #304051;padding:10px 0;gap:20px}.detail dt{color:#90a2b4}.detail dd{margin:0;text-align:right}.story{line-height:1.8;color:#c1cfde;white-space:pre-wrap}.linkbtn{margin-top:12px}.editor{max-width:680px}.editor form{display:grid;gap:15px}.editor label{font-size:13px;color:#b9c9d9;display:grid;gap:6px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.editor .check{display:flex;align-items:center}.check input{width:auto}.thumb{max-height:100px;max-width:90px}.foot{padding:40px 0;color:#a5b4c5}.foot strong{font:800 22px Outfit;color:white}.foot a{display:flex;gap:8px;align-items:center}footer{border-top:1px solid #273140}@media(max-width:800px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.filters{grid-template-columns:1fr 1fr}.search{grid-column:span 2}.detailgrid{grid-template-columns:1fr}.detailimage{height:280px}.hero{padding:65px 0}.stats{gap:22px}}@media(max-width:480px){.nav{min-height:66px}.brand{font-size:21px}.nav nav{gap:1px}.nav nav button{font-size:11px;padding:9px 7px}.hero h1{letter-spacing:-2px}.cardimage{height:220px}.cards{gap:10px}.cardinfo{padding:11px}.cardinfo h3{font-size:16px}.formgrid{grid-template-columns:1fr}.modal{padding:22px}.stats strong{font-size:23px}}
